-- Caja Pro: session-scoped financial summary.
CREATE OR REPLACE FUNCTION public.get_cash_register_summary(p_cash_register_id UUID) RETURNS TABLE (cash_register_id UUID, sales_count BIGINT, total_sales NUMERIC, cash_sales NUMERIC, card_sales NUMERIC, transfer_sales NUMERIC, other_sales NUMERIC, deposits NUMERIC, withdrawals NUMERIC, opening_amount NUMERIC, expected_cash NUMERIC) LANGUAGE sql STABLE SECURITY INVOKER SET search_path = public AS $$ WITH register AS (SELECT r.id, r.business_id, r.opened_at, COALESCE(r.closed_at, now()) AS end_at, r.opening_amount FROM public.cash_registers r WHERE r.id = p_cash_register_id AND public.is_business_member(r.business_id, auth.uid())), session_sales AS (SELECT s.id, s.total, lower(COALESCE(s.payment_method, '')) AS payment_method FROM public.sales s JOIN register r ON r.business_id = s.business_id WHERE s.status = 'paid' AND s.created_at >= r.opened_at AND s.created_at <= r.end_at), movement_totals AS (SELECT COALESCE(SUM(amount) FILTER (WHERE movement_type = 'deposit'), 0) AS deposits, COALESCE(SUM(amount) FILTER (WHERE movement_type = 'withdrawal'), 0) AS withdrawals FROM public.cash_register_movements m WHERE m.cash_register_id = p_cash_register_id), totals AS (SELECT COUNT(*) AS sales_count, COALESCE(SUM(total), 0) AS total_sales, COALESCE(SUM(total) FILTER (WHERE payment_method IN ('efectivo','cash')), 0) AS cash_sales, COALESCE(SUM(total) FILTER (WHERE payment_method IN ('tarjeta','card','debito','débito','credito','crédito')), 0) AS card_sales, COALESCE(SUM(total) FILTER (WHERE payment_method IN ('transferencia','transfer','bank_transfer')), 0) AS transfer_sales, COALESCE(SUM(total) FILTER (WHERE payment_method NOT IN ('efectivo','cash','tarjeta','card','debito','débito','credito','crédito','transferencia','transfer','bank_transfer')), 0) AS other_sales FROM session_sales) SELECT r.id, t.sales_count, t.total_sales, t.cash_sales, t.card_sales, t.transfer_sales, t.other_sales, m.deposits, m.withdrawals, r.opening_amount, r.opening_amount + t.cash_sales + m.deposits - m.withdrawals FROM register r CROSS JOIN totals t CROSS JOIN movement_totals m; $$;
REVOKE ALL ON FUNCTION public.get_cash_register_summary(UUID) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_cash_register_summary(UUID) TO authenticated;
